        new Recipe { Id = 5, Title = "Tacos Al Pastor", Category = "Mexican", Ingredients = "Pork shoulder\nPineapple\nAchiote paste\nGuajillo chiles\nCorn tortillas\nOnion\nCilantro\nLime", Steps = "1. Blend achiote, chiles, and pineapple juice into marinade.\n2. Marinate sliced pork overnight.\n3. Grill pork and pineapple slices.\n4. Chop pork and pineapple into small pieces.\n5. Warm tortillas.\n6. Assemble tacos with onion, cilantro, and lime.", AverageRating = 4.7, RatingCount = 18 },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Fold in diced onion, tomato, and jalapeño.\n4. Add lime juice and chopped cilantro.\n5. Season with salt.\n6. Serve immediately with tortilla chips.", AverageRating = 4.4, RatingCount = 10 },
        new Recipe { Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract", Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until thick.\n3. Fold chocolate mixture into eggs.\n4. Add flour and vanilla.\n5. Pour into greased ramekins.\n6. Bake at 425°F for 12 minutes. Center should be soft.", AverageRating = 4.9, RatingCount = 25 },
        new Recipe { Id = 8, Title = "Tiramisu", Category = "Desserts", Ingredients = "Ladyfingers\nMascarpone\nEspresso\nEgg yolks\nSugar\nCocoa powder\nMarsala wine", Steps = "1. Whisk yolks and sugar until pale.\n2. Fold in mascarpone.\n3. Mix espresso with Marsala.\n4. Dip ladyfingers briefly in coffee mixture.\n5. Layer ladyfingers and cream in a dish.\n6. Refrigerate 4 hours. Dust with cocoa before serving.", AverageRating = 4.7, RatingCount = 14 },
    };

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}
